import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Paper,
  Grid,
  Card,
  CardContent,
  Button,
  Box,
  Chip,
  Alert,
  CircularProgress,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Divider
} from '@mui/material';
import {
  School as SchoolIcon,
  Work as WorkIcon,
  Assignment as AssignmentIcon,
  CheckCircle as CheckCircleIcon,
  Pending as PendingIcon,
  TrendingUp as TrendingUpIcon
} from '@mui/icons-material';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { studentAPI } from '../services/api';

const StudentDashboard = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const response = await studentAPI.getDashboardStats();
      setDashboardData(response.data);
    } catch (err) {
      setError('Failed to load dashboard data');
      console.error('Dashboard error:', err);
    } finally {
      setLoading(false);
    }
  };

  const StatCard = ({ title, value, subtitle, icon, color = 'primary', onClick }) => (
    <Card 
      sx={{ 
        cursor: onClick ? 'pointer' : 'default',
        transition: 'all 0.3s ease',
        '&:hover': onClick ? { 
          transform: 'translateY(-4px)',
          boxShadow: 3 
        } : {}
      }}
      onClick={onClick}
    >
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
          <Box>
            <Typography color="textSecondary" gutterBottom variant="overline">
              {title}
            </Typography>
            <Typography variant="h4" component="div" sx={{ fontWeight: 'bold' }}>
              {value}
            </Typography>
            {subtitle && (
              <Typography variant="body2" color="textSecondary">
                {subtitle}
              </Typography>
            )}
          </Box>
          <Box sx={{ color: `${color}.main`, mt: 1 }}>
            {icon}
          </Box>
        </Box>
      </CardContent>
    </Card>
  );

  if (loading) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4, mb: 4, display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '50vh' }}>
        <Box textAlign="center">
          <CircularProgress size={60} />
          <Typography variant="h6" sx={{ mt: 2 }}>Loading Your Dashboard...</Typography>
        </Box>
      </Container>
    );
  }

  const data = dashboardData || {
    stats: {
      applications: 0,
      pendingApplications: 0,
      approvedApplications: 0,
      institutionsApplied: 0,
      jobsApplied: 0
    },
    recentApplications: [],
    recommendations: []
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      {/* Welcome Section */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" gutterBottom sx={{ fontWeight: 'bold' }}>
          Welcome back, {currentUser?.profile?.personalInfo?.firstName || 'Student'}!
        </Typography>
        <Typography variant="h6" color="textSecondary">
          Here's your academic and career journey overview
        </Typography>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError('')}>
          {error}
        </Alert>
      )}

      {/* Statistics Grid */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Total Applications"
            value={data.stats.applications}
            subtitle="All time"
            icon={<AssignmentIcon fontSize="large" />}
            color="primary"
            onClick={() => navigate('/applications')}
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Pending"
            value={data.stats.pendingApplications}
            subtitle="Awaiting review"
            icon={<PendingIcon fontSize="large" />}
            color="warning"
            onClick={() => navigate('/applications')}
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Approved"
            value={data.stats.approvedApplications}
            subtitle="Successful applications"
            icon={<CheckCircleIcon fontSize="large" />}
            color="success"
            onClick={() => navigate('/applications')}
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Institutions"
            value={data.stats.institutionsApplied}
            subtitle="Applied to"
            icon={<SchoolIcon fontSize="large" />}
            color="info"
            onClick={() => navigate('/institutions')}
          />
        </Grid>
      </Grid>

      <Grid container spacing={3}>
        {/* Profile Completion */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <TrendingUpIcon /> Profile Completion
              </Typography>
              
              <Box sx={{ mb: 3 }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                  <Typography variant="body2">Personal Information</Typography>
                  <Chip 
                    label={currentUser?.profile?.personalInfo ? "Complete" : "Incomplete"} 
                    color={currentUser?.profile?.personalInfo ? "success" : "warning"}
                    size="small"
                  />
                </Box>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                  <Typography variant="body2">Academic Records</Typography>
                  <Chip 
                    label={currentUser?.profile?.transcriptsUploaded ? "Uploaded" : "Pending"} 
                    color={currentUser?.profile?.transcriptsUploaded ? "success" : "warning"}
                    size="small"
                  />
                </Box>
                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                  <Typography variant="body2">Career Preferences</Typography>
                  <Chip 
                    label={currentUser?.profile?.careerPreferences ? "Set" : "Not Set"} 
                    color={currentUser?.profile?.careerPreferences ? "success" : "default"}
                    size="small"
                  />
                </Box>
              </Box>

              <Button 
                variant="contained" 
                fullWidth
                onClick={() => navigate('/profile')}
              >
                Complete Your Profile
              </Button>
            </CardContent>
          </Card>
        </Grid>

        {/* Quick Stats */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Application Status
              </Typography>
              
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <Typography variant="body2">Institution Applications</Typography>
                  <Chip label={data.stats.institutionsApplied} size="small" variant="outlined" />
                </Box>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <Typography variant="body2">Job Applications</Typography>
                  <Chip label={data.stats.jobsApplied} size="small" variant="outlined" />
                </Box>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <Typography variant="body2">Pending Reviews</Typography>
                  <Chip 
                    label={data.stats.pendingApplications} 
                    color="warning" 
                    size="small" 
                  />
                </Box>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <Typography variant="body2">Approved</Typography>
                  <Chip 
                    label={data.stats.approvedApplications} 
                    color="success" 
                    size="small" 
                  />
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        {/* Recent Applications */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <AssignmentIcon /> Recent Applications
              </Typography>
              
              {data.recentApplications && data.recentApplications.length > 0 ? (
                <List dense>
                  {data.recentApplications.slice(0, 4).map((application, index) => (
                    <React.Fragment key={application.id || index}>
                      <ListItem>
                        <ListItemIcon>
                          {application.type === 'job' ? <WorkIcon /> : <SchoolIcon />}
                        </ListItemIcon>
                        <ListItemText
                          primary={application.name}
                          secondary={
                            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                              <span>{application.type === 'job' ? 'Job' : 'Institution'}</span>
                              <Chip 
                                label={application.status} 
                                size="small"
                                color={
                                  application.status === 'approved' ? 'success' :
                                  application.status === 'rejected' ? 'error' : 'warning'
                                }
                              />
                            </Box>
                          }
                        />
                      </ListItem>
                      {index < data.recentApplications.slice(0, 4).length - 1 && <Divider />}
                    </React.Fragment>
                  ))}
                </List>
              ) : (
                <Typography variant="body2" color="textSecondary" sx={{ textAlign: 'center', py: 2 }}>
                  No recent applications. Start exploring institutions and jobs!
                </Typography>
              )}
              
              {data.recentApplications && data.recentApplications.length > 0 && (
                <Button 
                  size="small" 
                  onClick={() => navigate('/applications')}
                  sx={{ mt: 1 }}
                >
                  View All Applications
                </Button>
              )}
            </CardContent>
          </Card>
        </Grid>

        {/* Recommendations */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <TrendingUpIcon /> Your Next Steps
              </Typography>
              
              <List dense>
                <ListItem>
                  <ListItemIcon>
                    <SchoolIcon color="primary" />
                  </ListItemIcon>
                  <ListItemText
                    primary="Browse Institutions"
                    secondary="Find and apply to educational institutions"
                  />
                </ListItem>
                <Divider />
                <ListItem>
                  <ListItemIcon>
                    <WorkIcon color="secondary" />
                  </ListItemIcon>
                  <ListItemText
                    primary="Explore Job Opportunities"
                    secondary="Check out available positions from partner companies"
                  />
                </ListItem>
                <Divider />
                <ListItem>
                  <ListItemIcon>
                    <AssignmentIcon color="success" />
                  </ListItemIcon>
                  <ListItemText
                    primary="Track Applications"
                    secondary="Monitor your application status and updates"
                  />
                </ListItem>
              </List>

              <Box sx={{ display: 'flex', gap: 1, mt: 2 }}>
                <Button 
                  variant="outlined" 
                  size="small"
                  onClick={() => navigate('/institutions')}
                >
                  Find Institutions
                </Button>
                <Button 
                  variant="outlined" 
                  size="small"
                  onClick={() => navigate('/jobs')}
                >
                  Browse Jobs
                </Button>
              </Box>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Container>
  );
};

export default StudentDashboard;
